const SCOPE = new URL("./", self.location).pathname;
const relativ = (pfad) => (pfad.startsWith(SCOPE) ? pfad.slice(SCOPE.length) : null);

const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
const pruefsumme = async (antwort) => hex(await crypto.subtle.digest("SHA-1", await antwort.clone().arrayBuffer())).slice(0, 8);
// Holt eine Datei vom Server und prüft die Prüfsumme gegen HASH. Fehler oder falsche Summe: wirft.
async function holeGeprueft(pfad, cache) {
  const r = await fetch(new Request(pfad, { cache }));
  if (!r.ok) throw new Error(`HTTP ${r.status}: ${pfad}`);
  const soll = HASH[pfad === "./" ? "index.html" : pfad];
  if (soll && (await pruefsumme(r)) !== soll) throw new Error(`Prüfsumme falsch: ${pfad}`);
  return r;
}

self.addEventListener("install", (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(NAME);
    try { await Promise.all(DATEIEN.map(async (u) => c.put(new Request(u), await holeGeprueft(u, "reload")))); }
    catch (fehler) { await caches.delete(NAME); throw fehler; } // eine Datei falsch oder weg: Installation scheitert, die alte Fassung bleibt
  })());
});
self.addEventListener("activate", (e) => {
  e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => (k.startsWith("gc-") && k !== NAME) || (k.startsWith("gcv-") && k !== VENDOR)).map((k) => caches.delete(k))))
    .then(() => caches.open(FOTO_CACHE)).then(async (c) => { const gueltig = new Set(Object.keys(FOTOS_H).map(fotoSchluessel)); // alte Fotostände aufräumen
      for (const r of await c.keys()) { const u = new URL(r.url); const rel = nachladePfad(u.pathname); if (!rel || !gueltig.has(rel + u.search)) await c.delete(r); } })
    .then(() => self.clients.claim()));
});
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  const url = new URL(e.request.url);
  if (url.origin !== self.location.origin) return;
  const rel = nachladePfad(url.pathname);
  if (rel) { const k = fotoSchluessel(rel);
    if (k) { e.respondWith(caches.open(FOTO_CACHE).then(async (c) => { const t = await c.match(k); if (t) return t; const r = await fetch(k); if (r.ok) c.put(k, r.clone()); return r; }).catch(() => fetch(e.request))); return; } }
  if (url.pathname.includes("/vendor/")) {
    e.respondWith(caches.open(VENDOR).then(async (c) => { const t = await c.match(e.request); if (t) return t; const r = await fetch(e.request); if (r.ok) c.put(e.request, r.clone()); return r; }));
    return;
  }
  e.respondWith(caches.open(NAME).then(async (c) => {
    const treffer = await c.match(e.request, { ignoreSearch: true });
    if (treffer) return treffer;
    if (e.request.mode === "navigate") { const start = await c.match("index.html"); if (start) return start; }
    const pfad = relativ(url.pathname);
    if (pfad && HASH[pfad]) { // Datei der Nachlade-Liste, die noch fehlt: holen, prüfen, ablegen; falsche Prüfsumme = andere Fassung, nicht ausliefern
      const r = await fetch(e.request);
      if (r.ok && (await pruefsumme(r)) === HASH[pfad]) { c.put(e.request, r.clone()); return r; }
      return Response.error();
    }
    return fetch(e.request);
  }).catch(() => fetch(e.request)));
});

// Stufe 2: im Leerlauf nachladen. Läuft nur einmal gleichzeitig; was schon im Cache liegt, wird übersprungen.
let nachladeLauf = null;
async function sage(nachricht) { for (const k of await self.clients.matchAll({ includeUncontrolled: true })) k.postMessage(nachricht); }
async function nachladen() {
  const c = await caches.open(NAME), fc = await caches.open(FOTO_CACHE);
  const fehlt = [];
  for (const p of SPAETER) if (!(await c.match(p, { ignoreSearch: true }))) fehlt.push({ foto: false, p });
  for (const p of Object.keys(FOTOS_H)) if (!(await fc.match(fotoSchluessel(p)))) fehlt.push({ foto: true, p });
  const gesamt = SPAETER.length + Object.keys(FOTOS_H).length; let fertig = gesamt - fehlt.length; let luecke = false;
  const arbeiter = async () => {
    for (let x = fehlt.shift(); x; x = fehlt.shift()) {
      try {
        if (x.foto) { const k = fotoSchluessel(x.p); const r = await fetch(k, { cache: "no-cache" }); if (!r.ok) throw new Error(k); await fc.put(k, r); }
        else await c.put(new Request(x.p), await holeGeprueft(x.p, "no-cache"));
        fertig++;
      } catch { luecke = true; } // z. B. kein Netz: beim nächsten Start geht es hier weiter
    }
  };
  await Promise.all([arbeiter(), arbeiter(), arbeiter(), arbeiter()]);
  await sage({ art: "nachladen", stand: luecke ? "luecke" : "fertig", fertig, gesamt });
}
self.addEventListener("message", (e) => {
  if (e.data === "uebernehmen") self.skipWaiting();
  if (e.data === "nachladen") { if (!nachladeLauf) nachladeLauf = nachladen().finally(() => { nachladeLauf = null; }); e.waitUntil(nachladeLauf); }
});
